# ── Lookup-helpers ───────────────────────────────────────────────────────────
def get_concept(uri: str) -> dict | None:
    return CONCEPTS.get(uri)

def get_subclasses(uri: str, recursive: bool = False) -> list[str]:
    """Geeft directe (of alle recursieve) subklassen terug als URI-lijst."""
    direct = CONCEPTS.get(uri, {}).get("subclasses", [])
    if not recursive:
        return direct
    result = list(direct)
    for sub in direct:
        result.extend(get_subclasses(sub, recursive=True))
    return result

def label(uri: str) -> str:
    """Geeft het NL-label van een concept terug, of de naam als fallback."""
    c = CONCEPTS.get(uri, {})
    return c.get("label_nl") or c.get("name") or uri.split("#")[-1]

def find_by_name(name: str) -> str | None:
    """Zoek concept-URI op technische naam (bijv. 'ArbeidsOvereenkomst')."""
    for uri, info in CONCEPTS.items():
        if info["name"] == name:
            return uri
    return None